import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.DTdEDYjJ.js";const g=JSON.parse('{"title":"Bot Studio 架构与协议","description":"Bot Studio 的宿主与运行时架构、实际集成的开源项目，以及对外发表的规范和工具。","frontmatter":{"title":"Bot Studio 架构与协议","description":"Bot Studio 的宿主与运行时架构、实际集成的开源项目，以及对外发表的规范和工具。"},"headers":[],"relativePath":"development/architecture-report.md","filePath":"development/architecture-report.md"}'),n={name:"development/architecture-report.md"};function d(s,t,i,h,l,p){return r(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="bot-studio-架构与协议" tabindex="-1">Bot Studio 架构与协议 <a class="header-anchor" href="#bot-studio-架构与协议" aria-label="Permalink to &quot;Bot Studio 架构与协议&quot;">​</a></h1><p>Bot Studio 为常驻 Bot 管理身份、记忆、权限和任务。每个 Bot 绑定自己的执行器和工作空间，宿主负责受理、审批、停止和记录结果。模型、执行器、消息渠道与发布目标沿各自的接口接入。</p><p>本文覆盖 OpenBot 试点，以及后续已安装验收的 Bot Studio 1.0.33 桌面能力。仓库源码、桌面安装版和网站分别发布，功能可用性以相应版本为准。 <a href="./../guide/status.html">支持范围</a></p><h2 id="运行架构" tabindex="-1">运行架构 <a class="header-anchor" href="#运行架构" aria-label="Permalink to &quot;运行架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>桌面对话、任务与审批界面</span></span>
<span class="line"><span>  └─ Electron IPC → 桌面宿主 → 当前 Bot 的权限、绑定与任务记录</span></span>
<span class="line"><span>       ├─ API Bot → DSH/Cordis 或 Pi → 模型网关与获批工具</span></span>
<span class="line"><span>       ├─ 本机智能体 → Codex App Server、ACP 或 CLI → 原生会话</span></span>
<span class="line"><span>       ├─ 外部 AG-UI 执行器 → HTTP/SSE → 远端文本回复</span></span>
<span class="line"><span>       └─ 自建 Node → 独立任务、模型配置与浏览器工作屏幕</span></span>
<span class="line"><span></span></span>
<span class="line"><span>外部客户端、飞书、微信、Telegram</span></span>
<span class="line"><span>  └─ 各自的接入适配器 → 授权入口及目标 Bot → 任务与回执</span></span></code></pre></div><ul><li><strong>宿主持有业务状态。</strong> 每个 Bot 的身份、运行绑定、授权与任务结果由宿主维护。桌面 BotService 的部分执行入口已用 Cordis 装配，独立入口逐步收敛。自动化工具遵循执行范围和审批，取消、故障与结果未知分别记账。 <a href="./../concepts/architecture.html">身份、执行与连接</a></li><li><strong>执行器持有各自的运行会话。</strong> API Bot 默认使用 DSH，Pi 是可选内核。DSH 的插件、能力与工作目录按 Bot 装配。已绑定的本机智能体沿原生接口运行，1.0.33 新建 Codex Bot 默认走 App Server。模型连接独立配置。 <a href="./../guide/harness.html">Harness 适配</a> · <a href="./../guide/models.html">模型接入</a></li><li><strong>Node 负责远端执行。</strong> 桌面用显式授权连接自建 Node，读取任务与浏览器画面并接管。Node 保管自己的模型配置、浏览器资料、任务和审计。Bot 的记忆、附件与凭据迁移需要独立流程。 <a href="./../reference/node-api.html">Node API</a> · <a href="./../guide/runtime-and-data.html">运行与数据</a></li><li><strong>记忆由宿主授权。</strong> 默认使用原生记录，按 Bot、组织和空间限制读取。切换执行器时可继续使用当前获准的记忆，运行账号和私有会话留在各执行器的资料目录。 <a href="./../concepts/bot-communication.html">Bot 协作与通信边界</a></li></ul><h2 id="采用的协议" tabindex="-1">采用的协议 <a class="header-anchor" href="#采用的协议" aria-label="Permalink to &quot;采用的协议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议或接口</th><th>在 Bot Studio 中的用途</th><th>依据</th></tr></thead><tbody><tr><td>MCP</td><td>自建 Node 通过 stdio 给外部智能体提供交办、查询及取消工具。桌面发布单个 Bot 时提供 Streamable HTTP，调用者使用单独的 Bearer 凭据。</td><td><a href="https://modelcontextprotocol.io/specification/" target="_blank" rel="noreferrer">MCP 规范</a> · <a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">TypeScript SDK</a></td></tr><tr><td>ACP、Codex App Server</td><td>ACP 用于部分本机智能体的 stdio JSON-RPC 会话。Codex 走自己的 App Server 或 CLI，保持原有线程、运行与审批语义。</td><td><a href="https://github.com/agentclientprotocol/agent-client-protocol" target="_blank" rel="noreferrer">ACP</a> · <a href="https://developers.openai.com/codex/app-server/" target="_blank" rel="noreferrer">Codex App Server</a></td></tr><tr><td>AG-UI</td><td>使用官方客户端通过 HTTP/SSE 连接外部文字智能体。Bot 发布端也可用 AG-UI 观察已有请求，任务提交和取消走 HTTP API 或 MCP。</td><td><a href="https://github.com/ag-ui-protocol/ag-ui" target="_blank" rel="noreferrer">AG-UI 仓库</a></td></tr><tr><td>OpenAI Chat Completions 兼容接口</td><td>模型连接按适配器发起推理并接收流式响应。发布服务另有可选的 Chat Completions 兼容入口，按发布配置授权。</td><td><a href="./../guide/models.html">模型接入</a> · <a href="https://harzva.github.io/openbot/bot-engine-runtime/" target="_blank" rel="noreferrer">BotEngine 技术文档</a></td></tr><tr><td>飞书长连接、腾讯 iLink、Telegram Bot API</td><td>飞书用官方 SDK 接收与回复事件。微信自研渠道适配器按 iLink 协议完成扫码和私聊文字收发。Telegram 使用独立消息渠道。</td><td><a href="https://github.com/larksuite/node-sdk" target="_blank" rel="noreferrer">飞书 SDK</a> · <a href="https://github.com/Tencent/openclaw-weixin/blob/main/docs/protocol.md" target="_blank" rel="noreferrer">iLink 协议</a> · <a href="https://core.telegram.org/bots/api" target="_blank" rel="noreferrer">Telegram Bot API</a></td></tr><tr><td>OAuth 2.0 Device Flow</td><td>自建 Node 可为 GitHub 建立授权连接，持有凭据并按 Bot 分配只读动作。</td><td><a href="./../guide/app-authorizations.html">应用授权</a></td></tr><tr><td>HTTP(S) JSON、Bearer 与游标事件轮询</td><td>客户端连接自己的 Node，提交任务、查询进度和接管浏览器。跨账号的 A2A Adapter 仍待开发与互通验收。</td><td><a href="./../reference/node-api.html">Node API</a> · <a href="./../concepts/bot-communication.html">通信边界</a></td></tr></tbody></table><h2 id="实际使用的开源项目" tabindex="-1">实际使用的开源项目 <a class="header-anchor" href="#实际使用的开源项目" aria-label="Permalink to &quot;实际使用的开源项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>集成方式与验证范围</th><th>上游</th></tr></thead><tbody><tr><td><strong>DeepSeek Harness 与 Cordis</strong></td><td>固定 DSH SDK 和 Cordis 依赖。OpenBot 的适配层为各 Bot 配置独立运行目录、可信插件和宿主工具授权。桌面 BotService 也使用 Cordis 的服务装配。</td><td><a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness</a> · <a href="https://github.com/cordiverse/cordis" target="_blank" rel="noreferrer">Cordis</a></td></tr><tr><td><strong>Pi Agent Core 与 Pi AI</strong></td><td>嵌入的可选执行内核，由宿主管理模型、任务与授权。本机 Pi CLI 是单独的原生智能体接入项。</td><td><a href="https://github.com/earendil-works/pi" target="_blank" rel="noreferrer">Pi</a></td></tr><tr><td><strong>Electron 与 Playwright</strong></td><td>Electron 承载桌面 UI 和 IPC。Playwright 驱动受控 Chromium 浏览器任务，Node 为每个 Bot 隔离浏览器资料与输入队列。</td><td><a href="https://github.com/electron/electron" target="_blank" rel="noreferrer">Electron</a> · <a href="https://github.com/microsoft/playwright" target="_blank" rel="noreferrer">Playwright</a></td></tr><tr><td><strong>MCP、AG-UI 与飞书 SDK</strong></td><td>分别处理 MCP 接收与发布、远端 AG-UI 事件和飞书长连接。业务授权、目标 Bot 和任务回执由宿主处理。</td><td><a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">MCP SDK</a> · <a href="https://github.com/ag-ui-protocol/ag-ui" target="_blank" rel="noreferrer">AG-UI</a> · <a href="https://github.com/larksuite/node-sdk" target="_blank" rel="noreferrer">飞书 SDK</a></td></tr><tr><td><strong>Magpie 与 DSH × Magpie</strong></td><td>Magpie 独立运行。OpenBot 通过自己的宿主适配层加载 StrayDragon 的 DSH × Magpie 0.7.2 发布包，并将同步的模型目录导入命名连接。</td><td><a href="https://github.com/yetone/magpie" target="_blank" rel="noreferrer">Magpie</a> · <a href="https://github.com/Harzva/dsh-magpie-openbot/blob/main/PROVENANCE.json" target="_blank" rel="noreferrer">原包来源与校验</a></td></tr><tr><td><strong>OpenConnector</strong></td><td>实际运行过独立的账号连接试点，验证隔离的 Zammad 适配和有限的真实 GitHub 连接。验证范围是独立试点，桌面安装版的运行路径仍由 OpenBot 自己提供。</td><td><a href="https://github.com/oomol-lab/open-connector" target="_blank" rel="noreferrer">OpenConnector</a></td></tr><tr><td><strong>codex-host</strong></td><td>桌面集成改编了其中的 WorkBuddy 凭据引导代码，并随发行保留 LGPL-3.0 许可声明。</td><td><a href="https://github.com/BytePioneer-AI/codex-host" target="_blank" rel="noreferrer">codex-host</a></td></tr><tr><td><strong>腾讯 Hy-Memory</strong></td><td>实际使用 2.0.4 SDK 的 lite/Chroma 在隔离实验中验证 DSH 到 Pi 的跨执行器记忆交接，也验证了可选索引适配。实验使用确定性模型和 embedding，桌面默认仍读取 OpenBot 原生记忆。</td><td><a href="https://github.com/Tencent-Hunyuan/Hy-Memory" target="_blank" rel="noreferrer">Hy-Memory</a></td></tr></tbody></table><p>AstrBot 的引用限于 AgentApp Connector README 的展示方式。微信渠道采用独立实现的 iLink 适配器，OpenConnector 用于账号与应用连接的独立试点。</p><h2 id="我们对外发布的规范和工具" tabindex="-1">我们对外发布的规范和工具 <a class="header-anchor" href="#我们对外发布的规范和工具" aria-label="Permalink to &quot;我们对外发布的规范和工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输出</th><th>对外提供什么</th><th>发布状态</th></tr></thead><tbody><tr><td><strong>AnyBot Connector</strong></td><td><code>anybot.connector/0.1</code>、Alpha API、HTTP、MCP 和文本渠道绑定。统一不同 Bot 提供者的受理、查询、取消和权限契约。</td><td>公开 Alpha 源码，带可运行的确定性提供者和已隔离验证的 TeamBot 适配。 <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0001-connector-contract.md" target="_blank" rel="noreferrer">连接器规范</a> · <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0002-alpha-api.md" target="_blank" rel="noreferrer">Alpha API</a> · <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0003-bindings.md" target="_blank" rel="noreferrer">绑定</a></td></tr><tr><td><strong>AgentApp Connector</strong></td><td>用自有应用的 MCP URL 或 stdio 入口生成客户端配置，并提供按平台准备的申报模板与前置检查。覆盖 WorkBuddy、千问办公、豆包工作、ChatGPT/Codex、Cursor、Claude 和 ZCode 的 10 种配置目标。</td><td>源码与文档站已公开，市场材料均为 <code>NOT-SUBMITTED</code>。应用方填写自己的元数据，目标平台决定提交资格与审核。 <a href="https://github.com/Harzva/agentapp-connector" target="_blank" rel="noreferrer">仓库</a> · <a href="https://harzva.github.io/agentapp-connector/" target="_blank" rel="noreferrer">文档站</a></td></tr><tr><td><strong>Awesome Bot</strong></td><td>Bot 目录及机器可读发现页和 Bot 卡片。格式标识为 <code>awesome.bot.agent-discovery/1</code> 和 <code>awesome.bot.agent/1</code>，目录条目可以进入 Bot Studio 的模板发现流程。</td><td>已发布公开目录、源码与 GitHub Release。 <a href="https://harzva.github.io/awesome-bot/" target="_blank" rel="noreferrer">目录</a> · <a href="https://github.com/Harzva/awesome-bot/blob/main/docs/agent-integration.md" target="_blank" rel="noreferrer">格式说明</a> · <a href="https://github.com/Harzva/awesome-bot/releases/tag/v0.5.0" target="_blank" rel="noreferrer">Release</a></td></tr><tr><td><strong>OpenBot Node 与 BotEngine Runtime</strong></td><td>Node 自建接口文档。BotEngine Runtime 公开描述模型、独立工具、Harness、BotEngine Runtime 四层接口，包含 <code>published.chat@1</code> 能力和 <code>openbot.task-receipt/1</code> 回执标识。</td><td>公开技术文档。具体能力以产品版本、授权和实际接口为准。 <a href="./../reference/node-api.html">Node API</a> · <a href="https://harzva.github.io/openbot/bot-engine-runtime/" target="_blank" rel="noreferrer">BotEngine Runtime</a></td></tr><tr><td><strong>DSH × Magpie OpenBot 适配器</strong></td><td>桌面宿主通过固定版插件同步 Magpie 模型目录的实现，可供集成者参照和复用。</td><td>公开适配器源码。 <a href="https://github.com/Harzva/dsh-magpie-openbot" target="_blank" rel="noreferrer">仓库</a></td></tr><tr><td><strong>Codex Workbench Market</strong></td><td>DSH 工作台转为 Codex 工作台，提供独立页面、插件目录和离线分发包。目录和插件格式为 <code>openbot.codex-workbench-market/1</code> 与 <code>openbot.codex-workbench-plugin/1</code>。</td><td>1.1.0 已生成本地离线包，并集成到桌面安装版。独立仓库及发行包的公开发布尚未验证。</td></tr></tbody></table><p>桌面可以发布单个已配置的本机 API Bot，通过 HTTP 或 MCP 为每个调用方设置独立权限、会话和回执。桌面的内部执行契约 <code>openbot.bot-service.v1</code> 和 <code>openbot.execution.v1</code> 服务于宿主与执行器之间的协作。配置客户端、验证接入和准备市场材料的实际步骤见接入指南。 <a href="./integrate-and-publish.html">接入与发布</a></p>`,14)])])}const b=e(n,[["render",d]]);export{g as __pageData,b as default};
